package com.labresource.platform.sharing.repository;
import java.util.List;
import com.labresource.platform.sharing.entity.SharingListing; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import java.util.Optional;
public interface SharingListingRepository extends JpaRepository<SharingListing,Long>{ Optional<SharingListing> findByEquipmentId(Long id); List<SharingListing> findByEquipmentIdIn(List<Long> equipmentIds); @Query(value="select l from SharingListing l, Equipment e where e.id=l.equipmentId and l.active=true and (:owner is null or e.institutionId=:owner) and (:category is null or lower(e.category)=lower(:category)) and (:keyword is null or lower(e.name) like lower(concat('%',:keyword,'%')) or lower(coalesce(e.description,'')) like lower(concat('%',:keyword,'%')) or lower(coalesce(e.assetTag,'')) like lower(concat('%',:keyword,'%'))) and (:exclude is null or e.institutionId<>:exclude)",countQuery="select count(l) from SharingListing l, Equipment e where e.id=l.equipmentId and l.active=true and (:owner is null or e.institutionId=:owner) and (:category is null or lower(e.category)=lower(:category)) and (:keyword is null or lower(e.name) like lower(concat('%',:keyword,'%')) or lower(coalesce(e.description,'')) like lower(concat('%',:keyword,'%')) or lower(coalesce(e.assetTag,'')) like lower(concat('%',:keyword,'%'))) and (:exclude is null or e.institutionId<>:exclude)") Page<SharingListing> discover(@Param("owner")Long owner,@Param("category")String category,@Param("keyword")String keyword,@Param("exclude")Long exclude,Pageable pageable); }
